Sure! Below is a simple YAML parser written in Go without using any third-party libraries. This parser will handle basic YAML structures, including simple key-value pairs and nested mappings.

```go
package main

import (
	"fmt"
	"strings"
)

type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	root := YAMLNode{}
	currentNode := &root
	currentIndent := -1

	for _, line := range lines {
		indent := getIndent(line)
		line = strings.TrimSpace(line)

		if line == "" {
			continue
		}

		if indent > currentIndent {
			// Start a new child node
			currentNode[line] = YAMLNode{}
			currentNode = currentNode[line].(YAMLNode)
			currentIndent = indent
		} else if indent < currentIndent {
			// Go up to the parent node
			for i := 0; i < currentIndent-indent; i++ {
				currentNode = currentNode.Parent()
			}
			currentIndent = indent
		} else {
			// Same indent, so it's a sibling or the same level
			currentNode = currentNode.Parent()
			currentNode[line] = parseSimpleValue(strings.TrimSpace(line))
			currentNode = &root
			currentIndent = -1
		}
	}

	return root
}

func getIndent(s string) int {
	return len(s) - len(strings.TrimLeft(s, " "))
}

func parseSimpleValue(value string) interface{} {
	// Simple value parsing
	if value == "true" {
		return true
	} else if value == "false" {
		return false
	} else if value == "null" {
		return nil
	} else {
		return value
	}
}

func (n YAMLNode) Parent() interface{} {
	parent := YAMLNode{}
	for k, v := range n {
		if k == "" {
			continue
		}
		parent[k] = v
	}
	return parent
}

func main() {
	yamlInput := `name: John Doe
age: 30
isStudent: false
address:
  street: 123 Main St
  city: Anytown
  zip: 12345
`

	parsedYAML := ParseYAML(yamlInput)
	fmt.Printf("%v\n", parsedYAML)
}
```

### Explanation:

1. **YAMLNode**: This is a map that represents a YAML node. It can hold key-value pairs where the value can be any type (including another `YAMLNode` for nested structures).

2. **ParseYAML**: This function splits the input string into lines and calls `parseYAMLLines` to parse the lines.

3. **parseYAMLLines**: This function processes each line to determine its indentation level and constructs the YAML tree accordingly.

4. **getIndent**: This function calculates the indentation level of a line by counting the number of leading spaces.

5. **parseSimpleValue**: This function handles simple value parsing, converting strings like "true", "false", and "null" to their corresponding Go types.

6. **Parent**: This helper function is used to get the parent node when going up the tree.

### Example Output:

Given the input YAML string, the output will be:

```go
map[address:map[city:Anytown street:123 Main St zip:12345] age:30 isStudent:false name:John Doe]
```

This parser handles basic YAML structures and can be extended to handle more complex cases as needed.
